using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests;

/// <summary>
/// Tests for NotificationService: send (both overloads), receive, markAsRead,
/// generateMessage logic, queue cap, and dispose.
/// </summary>
public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut = new();

    /// <summary>Drain the static queue to ensure test isolation.</summary>
    public NotificationServiceTests()
    {
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose() => _sut.Dispose();

    // ── SendNotification (4-param overload) ──────────────────────────

    [Theory]
    [InlineData(EntityOperation.CREATE, "New Course 'Intro to C#' has been created")]
    [InlineData(EntityOperation.UPDATE, "Course 'Intro to C#' has been updated")]
    [InlineData(EntityOperation.DELETE, "Course 'Intro to C#' has been deleted")]
    public void SendNotification_WithDisplayName_GeneratesCorrectMessage(EntityOperation op, string expectedMessage)
    {
        // Act
        _sut.SendNotification("Course", "101", "Intro to C#", op, "admin");

        // Assert
        var n = _sut.ReceiveNotification();
        Assert.NotNull(n);
        Assert.Equal("Course", n!.EntityType);
        Assert.Equal("101", n.EntityId);
        Assert.Equal(op.ToString(), n.Operation);
        Assert.Equal(expectedMessage, n.Message);
        Assert.Equal("admin", n.CreatedBy);
        Assert.False(n.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdFallback()
    {
        // Act — 4-param overload (no displayName)
        _sut.SendNotification("Student", "42", EntityOperation.CREATE, "teacher");

        // Assert
        var n = _sut.ReceiveNotification();
        Assert.NotNull(n);
        Assert.Equal("New Student (ID: 42) has been created", n!.Message);
        Assert.Equal("teacher", n.CreatedBy);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        _sut.SendNotification("Dept", "7", EntityOperation.UPDATE);

        var n = _sut.ReceiveNotification();
        Assert.NotNull(n);
        Assert.Equal("System", n!.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithWhitespaceDisplayName_UsesIdFallback()
    {
        _sut.SendNotification("Course", "99", "   ", EntityOperation.DELETE);

        var n = _sut.ReceiveNotification();
        Assert.NotNull(n);
        Assert.Contains("(ID: 99)", n!.Message);
    }

    [Fact]
    public void SendNotification_UnknownOperation_FallsToDefault()
    {
        // EntityOperation has only 3 values; cast an int outside the enum
        _sut.SendNotification("X", "1", "Thing", (EntityOperation)999);

        var n = _sut.ReceiveNotification();
        Assert.NotNull(n);
        Assert.Contains("operation: 999", n!.Message);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        var before = DateTime.Now.AddSeconds(-2);
        _sut.SendNotification("E", "1", EntityOperation.CREATE);
        var after = DateTime.Now.AddSeconds(2);

        var n = _sut.ReceiveNotification();
        Assert.NotNull(n);
        Assert.InRange(n!.CreatedAt, before, after);
    }

    // ── ReceiveNotification ──────────────────────────────────────────

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        Assert.Null(_sut.ReceiveNotification());
    }

    [Fact]
    public void ReceiveNotification_MultipleItems_ReturnsFIFO()
    {
        _sut.SendNotification("A", "1", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", EntityOperation.UPDATE);

        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();
        Assert.Equal("A", first!.EntityType);
        Assert.Equal("B", second!.EntityType);
    }

    // ── MarkAsRead ───────────────────────────────────────────────────

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op, but should not throw
        var ex = Record.Exception(() => _sut.MarkAsRead(42));
        Assert.Null(ex);
    }

    // ── Queue cap ────────────────────────────────────────────────────

    [Fact]
    public void SendNotification_ExceedsCap_OldItemsRemoved()
    {
        // Queue cap is 500; send 510 items and verify oldest are dropped
        for (int i = 0; i < 510; i++)
        {
            _sut.SendNotification("T", i.ToString(), EntityOperation.CREATE);
        }

        // Drain all and count — should be ≤ 500
        int count = 0;
        while (_sut.ReceiveNotification() != null) count++;
        Assert.InRange(count, 1, 500);
    }

    // ── Dispose ──────────────────────────────────────────────────────

    [Fact]
    public void Dispose_CanBeCalledMultipleTimes()
    {
        var svc = new NotificationService();
        svc.Dispose();
        var ex = Record.Exception(() => svc.Dispose());
        Assert.Null(ex);
    }
}

