namespace ContosoUniversity.Tests;

/// <summary>
/// Tests for PaginatedList&lt;T&gt;: Create, HasPreviousPage, HasNextPage,
/// TotalPages calculation, and edge cases (empty, single page, multiple pages).
/// </summary>
public class PaginatedListTests
{
    private static IQueryable<int> Range(int count) =>
        Enumerable.Range(1, count).AsQueryable();

    // ── Create / TotalPages ──────────────────────────────────────────

    [Fact]
    public void Create_EmptySource_ReturnsEmptyListWithZeroPages()
    {
        var result = PaginatedList<int>.Create(Range(0), 1, 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
        Assert.Equal(1, result.PageIndex);
    }

    [Theory]
    [InlineData(10, 10, 1)]   // exactly 1 page
    [InlineData(11, 10, 2)]   // just over 1 page
    [InlineData(20, 10, 2)]   // exactly 2 pages
    [InlineData(25, 10, 3)]   // 3 pages (last page partial)
    [InlineData(1, 5, 1)]     // single item
    public void Create_VariousCounts_CorrectTotalPages(int total, int pageSize, int expectedPages)
    {
        var result = PaginatedList<int>.Create(Range(total), 1, pageSize);

        Assert.Equal(expectedPages, result.TotalPages);
    }

    [Fact]
    public void Create_FirstPage_ContainsCorrectItems()
    {
        var result = PaginatedList<int>.Create(Range(25), 1, 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
    }

    [Fact]
    public void Create_MiddlePage_ContainsCorrectItems()
    {
