using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests;

public class HomeControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly HomeController _sut;

    public HomeControllerTests()
    {
        _context = TestHelpers.CreateContext();
        _sut = new HomeController(_context);
        _sut.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
    }

    public void Dispose()
    {
        _sut.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _sut.Index();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void About_EmptyDatabase_ReturnsEmptyList()
    {
        var result = _sut.About();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
        Assert.Empty(model);
    }

    [Fact]
    public void About_WithStudents_ReturnsGroupedByEnrollmentDate()
    {
        // Arrange
        var date1 = new DateTime(2023, 9, 1);
        var date2 = new DateTime(2024, 1, 15);
        _context.Students.AddRange(
            new Student { LastName = "A", FirstMidName = "X", EnrollmentDate = date1 },
            new Student { LastName = "B", FirstMidName = "Y", EnrollmentDate = date1 },
            new Student { LastName = "C", FirstMidName = "Z", EnrollmentDate = date2 }
        );
        _context.SaveChanges();

        // Act
        var result = _sut.About();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
        Assert.Equal(2, model.Count);

        var group1 = model.Single(g => g.EnrollmentDate == date1);
        Assert.Equal(2, group1.StudentCount);

        var group2 = model.Single(g => g.EnrollmentDate == date2);
        Assert.Equal(1, group2.StudentCount);
    }

    [Fact]
    public void Contact_SetsViewBagMessage()
    {
        var result = _sut.Contact();

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal("Your contact page.", _sut.ViewBag.Message);
    }

    [Fact]
    public void Error_ReturnsViewResult()
    {
        var result = _sut.Error();
        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Unauthorized_SetsViewBagMessage()
    {
        var result = _sut.Unauthorized();

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal("You don't have permission to access this resource.", _sut.ViewBag.Message);
    }
}

