using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _sut;

    public NotificationsControllerTests()
    {
        _context = TestHelpers.CreateContext();
        _sut = new NotificationsController(_context);
        _sut.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };

        // Drain static notification queue for isolation
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        svc.Dispose();
    }

    public void Dispose()
    {
        _sut.Dispose();
        _context.Dispose();
    }

    // ── GetNotifications ─────────────────────────────────────────────

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
    {
        var result = _sut.GetNotifications();

        Assert.IsType<JsonResult>(result);
        dynamic value = result.Value!;
        var type = value.GetType();
        Assert.True((bool)type.GetProperty("success")!.GetValue(value));
        Assert.Equal(0, (int)type.GetProperty("count")!.GetValue(value));
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsThem()
    {
        // Arrange — push 3 notifications via the static queue
        var svc = new NotificationService();
        svc.SendNotification("A", "1", EntityOperation.CREATE);
        svc.SendNotification("B", "2", EntityOperation.UPDATE);
        svc.SendNotification("C", "3", EntityOperation.DELETE);

        // Act
        var result = _sut.GetNotifications();

        // Assert
        dynamic value = result.Value!;
        var type = value.GetType();
        Assert.True((bool)type.GetProperty("success")!.GetValue(value));
        Assert.Equal(3, (int)type.GetProperty("count")!.GetValue(value));

        var notifications = (IEnumerable<Notification>)type.GetProperty("notifications")!.GetValue(value);
        Assert.Equal(3, notifications.Count());
        svc.Dispose();
    }

    [Fact]
    public void GetNotifications_MoreThan10_LimitsTo10()
    {
        // Arrange
        var svc = new NotificationService();
        for (int i = 0; i < 15; i++)
        {
            svc.SendNotification("X", i.ToString(), EntityOperation.CREATE);
        }

        // Act
        var result = _sut.GetNotifications();

        // Assert
        dynamic value = result.Value!;
        var type = value.GetType();
        Assert.Equal(10, (int)type.GetProperty("count")!.GetValue(value));
        svc.Dispose();
    }

    // ── MarkAsRead ───────────────────────────────────────────────────

    [Fact]
    public void MarkAsRead_ReturnsSuccess()
    {
        var result = _sut.MarkAsRead(1);

        Assert.IsType<JsonResult>(result);
        dynamic value = result.Value!;
        var type = value.GetType();
        Assert.True((bool)type.GetProperty("success")!.GetValue(value));
    }

    // ── Index ────────────────────────────────────────────────────────

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _sut.Index();
        Assert.IsType<ViewResult>(result);
    }
}

