using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Net;

namespace ContosoUniversity.Tests;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _sut;

    public StudentsControllerTests()
    {
        _context = TestHelpers.CreateContext();
        _sut = new StudentsController(_context);
        _sut.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };

        // Drain static notification queue
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        svc.Dispose();
    }

    public void Dispose()
    {
        _sut.Dispose();
        _context.Dispose();
    }

    private void SeedStudents()
    {
        _context.Students.AddRange(
            new Student { LastName = "Anderson", FirstMidName = "Alice", EnrollmentDate = new DateTime(2023, 9, 1) },
            new Student { LastName = "Brown", FirstMidName = "Bob", EnrollmentDate = new DateTime(2024, 1, 15) },
            new Student { LastName = "Clark", FirstMidName = "Carol", EnrollmentDate = new DateTime(2023, 6, 1) },
            new Student { LastName = "Davis", FirstMidName = "Dan", EnrollmentDate = new DateTime(2024, 2, 1) },
            new Student { LastName = "Evans", FirstMidName = "Eve", EnrollmentDate = new DateTime(2023, 9, 1) }
        );
        _context.SaveChanges();
    }

    // ── Index ────────────────────────────────────────────────────────

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        SeedStudents();

        var result = _sut.Index(null, null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Anderson", model[0].LastName);
        Assert.Equal("Evans", model[^1].LastName);
    }

    [Fact]
    public void Index_NameDescSort_OrdersByLastNameDescending()
    {
        SeedStudents();

        var result = _sut.Index("name_desc", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Evans", model[0].LastName);
        Assert.Equal("Anderson", model[^1].LastName);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        SeedStudents();

        var result = _sut.Index("Date", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        // Earliest date first: 2023-06-01
        Assert.Equal("Clark", model[0].LastName);
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        SeedStudents();

        var result = _sut.Index("date_desc", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        // Latest date first: 2024-02-01
        Assert.Equal("Davis", model[0].LastName);
    }

    [Fact]
    public void Index_SearchString_FiltersStudents()
    {
        SeedStudents();

        var result = _sut.Index(null, null, "Clark", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Clark", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersStudents()
    {
        SeedStudents();

        var result = _sut.Index(null, null, "Alice", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Anderson", model[0].LastName);
    }

    [Fact]
    public void Index_SearchString_ResetsPageToOne()
    {
        SeedStudents();

        var result = _sut.Index(null, null, "A", 3);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NoSearchString_UsesCurrentFilter()
    {
        SeedStudents();

        var result = _sut.Index(null, "Clark", null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Clark", model[0].LastName);
    }

    [Fact]
    public void Index_SetsViewBagSortParameters()
    {
        SeedStudents();

        _sut.Index(null, null, null, null);

        Assert.Equal("name_desc", (string)_sut.ViewBag.NameSortParm);
        Assert.Equal("Date", (string)_sut.ViewBag.DateSortParm);
    }

    [Fact]
    public void Index_WithSortOrder_SetsCorrectToggle()
    {
        SeedStudents();

        _sut.Index("Date", null, null, null);

        // When sortOrder == "Date", DateSortParm toggles to "date_desc"
        Assert.Equal("date_desc", (string)_sut.ViewBag.DateSortParm);
        // When sortOrder is not empty, NameSortParm resets to ""
        Assert.Equal("", (string)_sut.ViewBag.NameSortParm);
    }

    [Fact]
