    {
        var result = _sut.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsStudentWithEnrollments()
    {
        // Arrange
        var dept = new Department { Name = "CS", Budget = 100000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 101, Title = "Intro", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var student = new Student { LastName = "Test", FirstMidName = "User", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        _context.SaveChanges();

        _context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = 101, Grade = Grade.A });
        _context.SaveChanges();

        // Act
        var result = _sut.Details(student.ID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal("Test", model.LastName);
        Assert.NotNull(model.Enrollments);
        Assert.Single(model.Enrollments);
    }

    // ── Create GET ───────────────────────────────────────────────────

    [Fact]
    public void Create_GET_ReturnsViewWithDefaultEnrollmentDate()
    {
        var result = _sut.Create();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    // ── Create POST ──────────────────────────────────────────────────

    [Fact]
    public void Create_POST_ValidStudent_SavesAndRedirects()
    {
        var student = new Student
        {
            LastName = "New",
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(2024, 3, 1)
        };

        var result = _sut.Create(student);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
        Assert.Single(_context.Students);
        Assert.Equal("New", _context.Students.First().LastName);
    }

    [Fact]
    public void Create_POST_InvalidModelState_ReturnsView()
    {
        _sut.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            FirstMidName = "NoLast",
            EnrollmentDate = new DateTime(2024, 1, 1)
        };

        var result = _sut.Create(student);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Same(student, viewResult.Model);
        Assert.Empty(_context.Students);
    }

    [Fact]
    public void Create_POST_MinValueDate_AddsModelError()
    {
        var student = new Student
        {
            LastName = "Bad",
            FirstMidName = "Date",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _sut.Create(student);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.True(_sut.ModelState.ContainsKey("EnrollmentDate"));
        Assert.Empty(_context.Students);
    }

    [Fact]
    public void Create_POST_OutOfRangeDate_AddsModelError()
    {
        var student = new Student
        {
            LastName = "Bad",
            FirstMidName = "Range",
            EnrollmentDate = new DateTime(1000, 1, 1)
        };

        var result = _sut.Create(student);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.True(_sut.ModelState.ContainsKey("EnrollmentDate"));
    }

    // ── Edit GET ─────────────────────────────────────────────────────

    [Fact]
    public void Edit_GET_NullId_ReturnsBadRequest()
    {
        var result = _sut.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_GET_NotFound_ReturnsNotFound()
    {
        var result = _sut.Edit(999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_GET_ValidId_ReturnsStudentInView()
    {
        var student = new Student { LastName = "Edit", FirstMidName = "Me", EnrollmentDate = new DateTime(2024, 1, 1) };
        _context.Students.Add(student);
        _context.SaveChanges();

        var result = _sut.Edit(student.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal("Edit", model.LastName);
    }

    // ── Edit POST ────────────────────────────────────────────────────

    [Fact]
    public void Edit_POST_ValidUpdate_SavesAndRedirects()
    {
        var student = new Student { LastName = "Before", FirstMidName = "Edit", EnrollmentDate = new DateTime(2024, 1, 1) };
        _context.Students.Add(student);
        _context.SaveChanges();
        _context.Entry(student).State = EntityState.Detached;

        var updated = new Student
        {
            ID = student.ID,
            LastName = "After",
            FirstMidName = "Edit",
            EnrollmentDate = new DateTime(2024, 2, 1)
        };

        var result = _sut.Edit(updated);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Edit_POST_InvalidModelState_ReturnsView()
    {
        _sut.ModelState.AddModelError("LastName", "Required");
        var student = new Student { ID = 1, FirstMidName = "Test", EnrollmentDate = new DateTime(2024, 1, 1) };

        var result = _sut.Edit(student);

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Edit_POST_MinValueDate_AddsModelError()
    {
        var student = new Student
        {
            ID = 1,
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _sut.Edit(student);

        Assert.True(_sut.ModelState.ContainsKey("EnrollmentDate"));
    }

    // ── Delete GET ───────────────────────────────────────────────────

    [Fact]
    public void Delete_GET_NullId_ReturnsBadRequest()
    {
        var result = _sut.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_GET_NotFound_ReturnsNotFound()
    {
        var result = _sut.Delete(999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_GET_ValidId_ReturnsView()
    {
        var student = new Student { LastName = "Del", FirstMidName = "Me", EnrollmentDate = new DateTime(2024, 1, 1) };
        _context.Students.Add(student);
        _context.SaveChanges();

        var result = _sut.Delete(student.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal("Del", model.LastName);
    }

    // ── DeleteConfirmed ──────────────────────────────────────────────

    [Fact]
    public void DeleteConfirmed_RemovesStudentAndRedirects()
    {
        var student = new Student { LastName = "Gone", FirstMidName = "User", EnrollmentDate = new DateTime(2024, 1, 1) };
        _context.Students.Add(student);
        _context.SaveChanges();

        var result = _sut.DeleteConfirmed(student.ID);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
        Assert.Empty(_context.Students);
    }
}

