using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;
using System.Net;

namespace ContosoUniversity.Tests;

public class DepartmentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly DepartmentsController _sut;

    public DepartmentsControllerTests()
    {
        _context = TestHelpers.CreateContext();
        _sut = new DepartmentsController(_context);
        _sut.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };

        // Drain notification queue
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        svc.Dispose();
    }

    public void Dispose()
    {
        _sut.Dispose();
        _context.Dispose();
    }

    private Instructor SeedInstructor()
    {
        var instructor = new Instructor
        {
            LastName = "Smith",
            FirstMidName = "John",
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Department SeedDepartment(Instructor? admin = null)
    {
        admin ??= SeedInstructor();
        var dept = new Department
        {
            Name = "Computer Science",
            Budget = 250000,
            StartDate = new DateTime(2020, 9, 1),
            InstructorID = admin.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    // ── Index ────────────────────────────────────────────────────────

    [Fact]
    public void Index_ReturnsAllDepartmentsWithAdministrator()
    {
        var instructor = SeedInstructor();
        SeedDepartment(instructor);

        var result = _sut.Index();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Computer Science", model[0].Name);
        Assert.NotNull(model[0].Administrator);
        Assert.Equal("Smith", model[0].Administrator!.LastName);
    }

    // ── Details ──────────────────────────────────────────────────────

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _sut.Details(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Details_NotFound_ReturnsNotFound()
    {
        var result = _sut.Details(999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsDepartment()
    {
        var dept = SeedDepartment();

        var result = _sut.Details(dept.DepartmentID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Computer Science", model.Name);
        Assert.Equal(250000m, model.Budget);
    }

    // ── Create GET ───────────────────────────────────────────────────

    [Fact]
    public void Create_GET_SetsViewBagInstructorID()
    {
        SeedInstructor();

        var result = _sut.Create();

        Assert.IsType<ViewResult>(result);
        Assert.NotNull(_sut.ViewBag.InstructorID);
        Assert.IsType<SelectList>(_sut.ViewBag.InstructorID);
    }

    // ── Create POST ──────────────────────────────────────────────────

    [Fact]
    public void Create_POST_ValidDepartment_SavesAndRedirects()
    {
        var instructor = SeedInstructor();
        var dept = new Department
        {
            Name = "Physics",
            Budget = 100000,
            StartDate = new DateTime(2024, 1, 1),
            InstructorID = instructor.ID
        };

        var result = _sut.Create(dept);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
        Assert.Equal(1, _context.Departments.Count());
        Assert.Equal("Physics", _context.Departments.First().Name);
    }

    [Fact]
    public void Create_POST_InvalidModelState_ReturnsView()
    {
        _sut.ModelState.AddModelError("Name", "Required");
        var dept = new Department { Budget = 10000, StartDate = DateTime.Now };

        var result = _sut.Create(dept);

        Assert.IsType<ViewResult>(result);
        Assert.Empty(_context.Departments);
    }

    // ── Edit GET ─────────────────────────────────────────────────────

    [Fact]
    public void Edit_GET_NullId_ReturnsBadRequest()
    {
        var result = _sut.Edit(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_GET_NotFound_ReturnsNotFound()
    {
        var result = _sut.Edit(999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_GET_ValidId_ReturnsDepartmentAndSetsViewBag()
    {
        var dept = SeedDepartment();

        var result = _sut.Edit(dept.DepartmentID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Computer Science", model.Name);
        Assert.NotNull(_sut.ViewBag.InstructorID);
    }

    // ── Edit POST ────────────────────────────────────────────────────

    [Fact]
    public void Edit_POST_ValidUpdate_SavesAndRedirects()
    {
        var dept = SeedDepartment();
        _context.Entry(dept).State = EntityState.Detached;

        var updated = new Department
        {
            DepartmentID = dept.DepartmentID,
            Name = "Updated CS",
            Budget = 300000,
            StartDate = dept.StartDate,
            InstructorID = dept.InstructorID
        };

        var result = _sut.Edit(updated);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Edit_POST_InvalidModelState_ReturnsView()
    {
        _sut.ModelState.AddModelError("Name", "Required");
        var dept = new Department { DepartmentID = 1, Budget = 10000, StartDate = DateTime.Now };

        var result = _sut.Edit(dept);

        Assert.IsType<ViewResult>(result);
    }

    // ── Delete GET ───────────────────────────────────────────────────

    [Fact]
    public void Delete_GET_NullId_ReturnsBadRequest()
    {
        var result = _sut.Delete(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_GET_NotFound_ReturnsNotFound()
    {
        var result = _sut.Delete(999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_GET_ValidId_ReturnsDepartment()
    {
        var dept = SeedDepartment();

        var result = _sut.Delete(dept.DepartmentID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Computer Science", model.Name);
    }

    // ── DeleteConfirmed ──────────────────────────────────────────────

    [Fact]
    public void DeleteConfirmed_RemovesDepartmentAndRedirects()
    {
        var dept = SeedDepartment();

        var result = _sut.DeleteConfirmed(dept.DepartmentID);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
        Assert.Empty(_context.Departments);
    }
}

