[Fact]
public void HasPreviousPage_PageIndexExactlyOne_ReturnsFalse()
{
    // Guards against > becoming >= mutation
    var result = PaginatedList<int>.Create(Range(30), 1, 10);
    Assert.False(result.HasPreviousPage);
    Assert.Equal(1, result.PageIndex);
}

[Fact]
public void HasNextPage_PageIndexExactlyEqualsTotalPages_ReturnsFalse()
{
    // Guards against < becoming <= mutation
    var result = PaginatedList<int>.Create(Range(30), 3, 10);
    Assert.Equal(3, result.TotalPages);
    Assert.Equal(3, result.PageIndex);
    Assert.False(result.HasNextPage);
}

